// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(amount != c.currentDifficulty());
        uint256 difficultyBefore = c.currentDifficulty();
        vm.prank(actor);
        bool ok;
        try c.AdjustDifficulty(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok ? c.currentDifficulty() == difficultyBefore : true);
    }
}
